  IEnumerable<Song> AllSongs{get{return p.Folders.SelectMany(f=>f.Songs);}}
  List<Song> SelectedSongs(){if(v.LibraryMode=="Ordner"){var names=v.Groups.SelectedRows.Cast<DataGridViewRow>().OrderBy(r=>r.Index).Select(r=>r.Tag as Tuple<string,string>).Where(g=>g!=null&&g.Item1=="folder").Select(g=>g.Item2).ToArray();return names.SelectMany(name=>p.Folders.Where(f=>String.Equals(f.Name,name,StringComparison.OrdinalIgnoreCase)).SelectMany(f=>f.Songs)).GroupBy(song=>Path.GetFullPath(song.Source),StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();}return v.Songs.SelectedRows.Cast<DataGridViewRow>().OrderBy(r=>r.Index).Select(r=>r.Tag as Song).Where(s=>s!=null).ToList();}
