  HashSet<string> recentImportPaths;
  void PopulateLibrary(){
   CancelLibrarySearch();if(updatingLibrary)return;CaptureLibraryViews();searchIndex=null;if(!sideCommitting&&!refresh){v.Songs.EndEdit();CommitSideTags();}updatingLibrary=true;bool before=refresh;refresh=true;v.BeginLibraryUpdate();try{
    int artIndex=0;foreach(var item in AllSongs)item.StudioColorIndex=artIndex++;
    var entries=p.Folders.SelectMany(f=>f.Songs.Select(s=>Tuple.Create(f,s))).Where(x=>recentImportPaths==null||!String.IsNullOrWhiteSpace(v.SearchBox.Text)||recentImportPaths.Contains(Path.GetFullPath(x.Item2.Source))).Where(x=>(voiceQueryText==v.SearchBox.Text?LibrarySearch.VoiceMatches(x.Item2,voiceQueryText):LibrarySearch.Matches(x.Item2,x.Item1.Name,v.SearchBox.Text))).OrderByDescending(x=>SearchText.Relevance(v.SearchBox.Text,x.Item2.Artist+" "+x.Item2.Title)).ToList();
    v.SetLibraryCounters(LibraryCounter.FromSongs(AllSongs));
    bool showGroups=v.LibraryMode!="Titel";v.Groups.Visible=showGroups;v.Songs.Visible=!showGroups;v.SongPane.Visible=!showGroups&&!v.SongPane.IsHidden;
    if(showGroups){v.Groups.Rows.Clear();string field=v.LibraryMode=="Ordner"?"folder":v.LibraryMode=="Alben"?"album":"artist";v.Groups.Columns["Name"].HeaderText=v.LibraryMode;v.Groups.Columns["Info"].HeaderText=field=="folder"?"Pfad":field=="album"?"Interpreten":"Alben";var groups=entries.GroupBy(x=>field=="folder"?x.Item1.Name:field=="album"?x.Item2.Album??"":x.Item2.Artist??"").OrderBy(g=>g.Key,StringComparer.CurrentCultureIgnoreCase);foreach(var g in groups){int row=v.Groups.Rows.Add(String.IsNullOrEmpty(g.Key)?"(Ohne Angabe)":g.Key,g.Count(),field=="folder"?g.First().Item1.SourceDirectory:field=="album"?String.Join(", ",g.Select(x=>x.Item2.Artist).Distinct().Take(4)):g.Select(x=>x.Item2.Album).Distinct().Count()+" Alben");v.Groups.Rows[row].Tag=Tuple.Create(field,g.Key);}renderedGroupMode=v.LibraryMode;if(groupViewStates.TryGetValue(renderedGroupMode,out var groupState))groupState.Restore(v.Groups,null,false);else v.RestoreGroupSort();return;}
    if(libraryFolder!=null)entries=entries.Where(x=>x.Item1==libraryFolder).ToList();if(groupField!=null)entries=entries.Where(x=>(groupField=="album"?x.Item2.Album:x.Item2.Artist)==groupValue).ToList();
    var selected=SelectedSongs();v.Songs.Rows.Clear();foreach(var entry in entries){var song=entry.Item2;song.FolderName=entry.Item1.Name;int row=v.Songs.Rows.Add(song.Artist,song.Title,song.Album,Path.GetFileName(song.Source));var r=v.Songs.Rows[row];r.Tag=song;r.Cells["Tracknummer"].Value=song.Track;r.Cells["Jahr"].Value=song.Year;r.Cells["Genre"].Value=song.Genre;r.Cells["Dauer"].Value=song.Duration;r.Cells["Ordner"].Value=TagSchema.Value(song,"_directory");r.Cells["Tag"].Value=song.TagType;r.Cells["Bitrate"].Value=song.Bitrate>0?song.Bitrate.ToString():"";r.Cells["Dateipfad"].Value=TagSchema.Value(song,"_path");r.Cells["Kommentar"].Value=song.Comment;if(v.Songs.Columns.Contains("AcoustidId"))r.Cells["AcoustidId"].Value=song.AcoustidId;r.Selected=selected.Contains(song);}if(selected.Count==0)v.Songs.ClearSelection();
    titleViewState.Restore(v.Songs,EditedPath);TrackColumns.Load(v.Songs);v.Counts.Text=entries.Count.ToString("N0")+" angezeigte Titel · "+p.Folders.Count+" Ordner · "+(libraryFolder!=null?libraryFolder.Name:groupValue??"Gesamte Bibliothek");
   }finally{updatingLibrary=false;v.EndLibraryUpdate();RestoreActiveLibraryView();ApplySearchResultOrder();refresh=before;SyncSideTags(false);}
  }
  void StepSong(int direction){var order=playlistOrder!=null&&playlistOrder.Count>0?playlistOrder:v.Songs.Rows.Cast<DataGridViewRow>().Select(r=>r.Tag as Song).Where(s=>s!=null).ToList();if(order.Count==0)order=AllSongs.ToList();if(order.Count==0)return;int n=order.IndexOf(playerSong);var next=order[n<0?0:(n+direction+order.Count)%order.Count];LoadPlayer(next);StartPlayer();foreach(DataGridViewRow row in v.Songs.Rows)if(row.Tag==next&&!row.Displayed){v.Songs.FirstDisplayedScrollingRowIndex=row.Index;break;}}
  void HandleVoice(string[] alternatives){if(busy||alternatives.Length==0)return;string text=LibrarySearch.Normalize(alternatives[0]).Trim().TrimEnd('.','!');if(new[]{"pause","pausieren","anhalten"}.Contains(text)){RunPlayback(()=>{playback.Pause();UpdatePlayer();});return;}if(new[]{"stopp","stop","stoppen"}.Contains(text)){RunPlayback(StopPlayer);return;}if(new[]{"weiter","fortsetzen","wiedergabe","resume","continue","play"}.Contains(text)){RunPlayback(StartPlayer);return;}if(new[]{"nachster titel","nachstes lied","next"}.Contains(text)){RunPlayback(()=>StepSong(1));return;}if(new[]{"vorheriger titel","zuruck","previous"}.Contains(text)){RunPlayback(()=>StepSong(-1));return;}bool play;LibrarySearch.PlayTerm(alternatives[0],out play);lastVoiceHeard=LibrarySearch.VoiceTerm(alternatives[0]);string term=personalVoice.Apply(lastVoiceHeard);if(String.IsNullOrWhiteSpace(term))return;voiceQueryText=term;v.SearchBox.Text=term;QueueLibrarySearch(term,false);if(!play)return;var choices=alternatives.Select(x=>{bool ignored;return personalVoice.Apply(LibrarySearch.VoiceTerm(LibrarySearch.PlayTerm(x,out ignored)));});Song found=LibrarySearch.FindVoice(AllSongs,choices);if(found==null){v.Status.Text="Kein eindeutiger Titel erkannt – bitte einen Treffer doppelklicken.";return;}v.SearchBox.Clear();v.LibraryMode="Titel";libraryFolder=null;groupField=groupValue=null;PopulateLibrary();foreach(DataGridViewRow row in v.Songs.Rows)if(row.Tag==found){v.Songs.ClearSelection();row.Selected=true;v.Songs.CurrentCell=row.Cells[0];v.Songs.FirstDisplayedScrollingRowIndex=row.Index;break;}RunPlayback(()=>{LoadPlayer(found);StartPlayer();});}
