   if(new[]{"Coversuche","Coverbearbeitung","Covergestaltung","Cover zuweisen / exportieren"}.Contains(page)){OpenCoverSubmodule(page);return;}
   Panel panel;FlowLayoutPanel buttons;
   if(page=="Coversuche"||page=="Coverbearbeitung"||page=="Covergestaltung"||page=="Cover zuweisen / exportieren"||page=="Cover-Studio"){panel=ModulePage("Cover-Studio","Themenordner-Cover und eingebettete Titelcover bearbeiten. Die ausgewählten Titel und Ordner aus der Bibliothek bleiben verfügbar.");buttons=ModuleButtons(panel);buttons.Controls.Add(MainView.StudioButton("Ordnercover gestalten",()=>Run(DesignCover),true));buttons.Controls.Add(MainView.StudioButton("Cover-Serie",()=>Run(CoverSeries)));buttons.Controls.Add(MainView.StudioButton("Ordnercover laden",()=>Run(SetCover)));buttons.Controls.Add(MainView.StudioButton("Titelcover suchen / auswählen",()=>Run(SearchCover)));}
   else if(page=="Musikerkennung"){panel=ModulePage("Musikerkennung","Einen Titel in der Bibliothek markieren. Klang-Erkennung über AcoustID oder ACRCloud; Vorschläge werden vor der Übernahme angezeigt.");buttons=ModuleButtons(panel);buttons.Controls.Add(MainView.StudioButton("Mit Fingerabdruck erkennen",()=>Run(IdentifyFingerprints),true));buttons.Controls.Add(MainView.StudioButton("ACRCloud-Erkennung",()=>Run(IdentifySong)));buttons.Controls.Add(MainView.StudioButton("AcoustID-Zugang",()=>Run(FingerprintConfig)));buttons.Controls.Add(MainView.StudioButton("ACRCloud-Zugang",()=>Run(RecognitionConfig)));}
   else if(page=="Export"){panel=ModulePage("Export","Musikbox-Export erstellt nummerierte Ordner mit bis zu 99 Titeln. Katalogexport umfasst alle geladenen Titel. Quelldateien bleiben erhalten.");buttons=ModuleButtons(panel);buttons.Controls.Add(MainView.StudioButton("Musikbox exportieren",()=>Run(StartExport),true));buttons.Controls.Add(MainView.StudioButton("Katalog als CSV",()=>Run(ExportCatalog)));buttons.Controls.Add(MainView.StudioButton("Tag-Dateikopien",()=>Run(WriteTagCopies)));buttons.Controls.Add(MainView.StudioButton("Sortiervorschau",()=>Run(Preview)));buttons.Controls.Add(MainView.StudioButton("Sammlung prüfen",()=>Run(Check)));}
   else{panel=ModulePage("Einstellungen","Projekte, Sicherungen, Audioverarbeitung und Sprachsteuerung.");buttons=ModuleButtons(panel);buttons.Controls.Add(MainView.StudioButton("Audio-Einstellungen",()=>Run(GainSettings)));buttons.Controls.Add(MainView.StudioButton("Projekt öffnen",()=>Run(Open)));buttons.Controls.Add(MainView.StudioButton("Projekt speichern",()=>Run(Save)));buttons.Controls.Add(MainView.StudioButton("Projektsicherungen",()=>Run(RecoverBackup)));buttons.Controls.Add(MainView.StudioButton("Dateien wiederfinden",()=>Run(RelinkSources)));var model=new StudioComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=245};model.Items.AddRange(new object[]{"Sprachmodell: automatisch","Sprachmodell: schnell"});bool hasSmallModel=File.Exists(PortablePaths.Tool(Path.Combine("whisper","ggml-small.bin")));if(hasSmallModel)model.Items.Add("Sprachmodell: genauer");string preference=Path.Combine(PortablePaths.Data,"Sprachmodell.txt");string chosen=File.Exists(preference)?File.ReadAllText(preference).Trim():"auto";model.SelectedIndex=chosen=="base"?1:chosen=="small"&&hasSmallModel?2:0;model.SelectedIndexChanged+=(s,e)=>{voice.Stop();File.WriteAllText(preference,model.SelectedIndex==1?"base":model.SelectedIndex==2?"small":"auto");};buttons.Controls.Add(model);
#if NET8_0_OR_GREATER
 var inputs=new StudioComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=300};inputs.Items.Add("Mikrofon: Windows-Standard (automatisch)");try{inputs.Items.AddRange(VoiceService.InputDevices());}catch(Exception ex){v.Status.Text="Aufnahmegeräte: "+ex.Message;}string micFile=Path.Combine(PortablePaths.Data,"Mikrofon.txt");string savedMic=File.Exists(micFile)?File.ReadAllText(micFile):"";inputs.SelectedIndex=0;for(int i=1;i<inputs.Items.Count;i++)if((string)inputs.Items[i]==savedMic)inputs.SelectedIndex=i;inputs.SelectedIndexChanged+=(s,e)=>{voice.Stop();Directory.CreateDirectory(PortablePaths.Data);File.WriteAllText(micFile,inputs.SelectedIndex==0?"":(string)inputs.SelectedItem);};buttons.Controls.Add(inputs);
#endif
 buttons.Controls.Add(MainView.StudioButton("Persönliche Sprachkorrekturen",EditVoiceCorrections));buttons.Controls.Add(MainView.StudioButton("Mikrofon starten / beenden",()=>v.Microphone.PerformClick()));}
