  void EditVoiceCorrections(){using(var form=new ModernForm{Text="Persönliche Sprachkorrekturen · lokale Suchzuordnung",Width=760,Height=520,StartPosition=FormStartPosition.CenterParent}){
   var list=new StudioListBox{Dock=DockStyle.Fill};var heard=new StudioTextBox{Width=260,Text=lastVoiceHeard??v.SearchBox.Text};var target=new StudioTextBox{Width=330};var selected=SelectedSongs().FirstOrDefault();if(selected!=null)target.Text=selected.Artist+" "+selected.Title;
   var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new Padding(12)};
   bar.Controls.Add(new Label{Text="Erkannt",AutoSize=true});bar.Controls.Add(heard);bar.Controls.Add(new Label{Text="Richtiger Suchtext",AutoSize=true});bar.Controls.Add(target);
   Action reload=()=>{list.Items.Clear();foreach(var key in personalVoice.Items.Keys.OrderBy(x=>x))list.Items.Add(key);};
   list.SelectedIndexChanged+=(s,e)=>{var key=list.SelectedItem as string;if(key!=null){heard.Text=key;target.Text=personalVoice.Items[key];}};
   bar.Controls.Add(MainView.StudioButton("Speichern",()=>{try{personalVoice.Set(heard.Text,target.Text);reload();}catch(Exception ex){AppMessage.Show(form,ex.Message);}}));
   bar.Controls.Add(MainView.StudioButton("Löschen",()=>{personalVoice.Remove(heard.Text);reload();}));form.Controls.Add(list);form.Controls.Add(bar);reload();ModernTheme.Apply(form);form.ShowDialog(v);
  }}
  void ExportCatalog(){using(var d=new AppSaveFileDialog{Filter="CSV-Katalog|*.csv",FileName="Musikbox-Katalog.csv"})if(d.ShowDialog(v)==DialogResult.OK){var rows=new List<string>{"Ordner;Interpret;Titel;Album;Jahr;Genre;Kommentar;Dauer;Dateipfad"};foreach(var f in p.Folders)foreach(var s in f.Songs)rows.Add(String.Join(";",new[]{f.Name,s.Artist,s.Title,s.Album,s.Year,s.Genre,s.Comment,PlayerView.Format((int)(s.Duration*1000)),s.Source}.Select(x=>"\""+(x??"").Replace("\"","\"\"")+"\"")));File.WriteAllLines(d.FileName,rows,new UTF8Encoding(true));v.Status.Text="Katalog gespeichert: "+d.FileName;}}
  async void WriteTagCopies(){var songs=SelectedSongs();if(songs.Count==0){AppMessage.Show(v,"Bitte zuerst die gewünschten Titel in der Bibliothek markieren.");return;}string parent;using(var d=new AppFolderDialog{Description="Ziel für neue Dateikopien mit bearbeiteten Tags"}){if(d.ShowDialog(v)!=DialogResult.OK)return;parent=d.SelectedPath;}await RunStudioBatch("Tags schreiben",token=>{string stage=BatchFiles.Stage(parent);try{for(int i=0;i<songs.Count;i++){token.ThrowIfCancellationRequested();var s=songs[i];string path=Path.Combine(stage,(i+1).ToString("D4")+" - "+Rules.SafeName(s.Artist+" - "+s.Title)+Path.GetExtension(s.Source));MediaMetadata.WriteCopy(s,s.Album??"",path,()=>token.ThrowIfCancellationRequested());}return BatchFiles.Commit(stage,"Tags");}catch{BatchFiles.Cleanup(stage);throw;}});}
  async Task RunStudioBatch(string name,Func<CancellationToken,string> action,Action<string> report=null){if(busy)return;cancel=new CancellationTokenSource();SetBusy(true);v.Status.Text=name+" …";try{string result=await Task.Run(()=>action(cancel.Token));if(report!=null)report(name+" abgeschlossen\r\n"+result);else v.Report(name+" abgeschlossen",result);}catch(OperationCanceledException){v.Status.Text=name+" abgebrochen.";if(report!=null)report(v.Status.Text);}catch(Exception ex){if(report!=null)report("Fehler: "+ex.Message);else AppMessage.Show(v,ex.Message,name);}finally{cancel.Dispose();cancel=null;SetBusy(false);}}
 }
 public static class BatchFiles {
  public static string Stage(string parent){string path=Path.Combine(parent,".Musikbox-unvollstaendig-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
  public static string Commit(string stage,string label){string target=Path.Combine(Path.GetDirectoryName(stage),"Musikbox-"+label+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.Move(stage,target);return target;}
  public static void Cleanup(string stage){try{if(Directory.Exists(stage))Directory.Delete(stage,true);}catch{}}
 }
